static const int MAX_DIM = 16;

static void dense(const float* in, int in_dim, const float* W, const float* B,
                  int out_dim, float* out, int is_output) {
  for (int o = 0; o < out_dim; o++) {
    float acc = B[o];
    for (int i = 0; i < in_dim; i++) acc += W[o * in_dim + i] * in[i];
    out[o] = is_output ? tanhf(acc) : tanhf(acc);
  }
}

// obs[]: leituras normalizadas 0..1 (0 = obstáculo colado, 1 = caminho livre)
// out[]: PWM assinado por motor, -1..1
static void policy_forward(const float* obs, float* out) {
  static float bufA[MAX_DIM];
  static float bufB[MAX_DIM];
  for (int i = 0; i < NUM_SENSORS; i++) bufA[i] = obs[i];
  dense(bufA, L0_IN, L0_W, L0_B, L0_OUT, bufB, 0);
  dense(bufB, L1_IN, L1_W, L1_B, L1_OUT, bufA, 0);
  dense(bufA, L2_IN, L2_W, L2_B, L2_OUT, bufB, 1);
  for (int i = 0; i < NUM_MOTORS; i++) {
    float v = bufB[i];
    if (v > 1.0f) v = 1.0f;
    if (v < -1.0f) v = -1.0f;
    out[i] = v;
  }
}
